def run(cmd, check=True):
    print(f"$ {cmd}")
    r = subprocess.run(cmd, shell=True, stdout=sys.stdout, stderr=sys.stderr, text=True)
    if check and r.returncode != 0:
        print(f"FAILED: code {r.returncode}"); sys.exit(1)
    return r

# ============================================================================
