EMBEDDED_FILES = {
    'finetune_v4.py': '"""\nfinetune_v4.py\n==============\nv4 ENHANCED finetuning script — for gold standard dataset (LLM-verified + re-verified).\n\nUPGRADES over v3:\n  1. Oversampling: negative→400, positive→600 (reduces imbalance)\n  2. Focal gamma: 2.5→3.0, Label smoothing: 0.05→0.07\n  3. LoRA dropout: 0.15→0.20, Mixup alpha: 0.2→0.3, prob: 40%\n  4. Class weights: 1/sqrt(freq)→1/log(freq+1) (gentler)\n  5. Entity-stratified K-fold (GroupKFold by entity)\n  6. Entity as explicit premise: "Tentang {entity}"\n  7. Epochs: 20→18, SWA start: 5→4\n\nUsage:\n  python finetune_v4.py --task sentiment --kfold 5\n  python finetune_v4.py --task relevancy --kfold 5\n\nUPGRADES over finetune.py (v1):\n  1. K-Fold Cross-Validation (5-fold stratified) — robust evaluation\n  2. Adversarial Training (PGD on embeddings) — fights input perturbations\n  3. Mixup Augmentation — interpolates sentence pairs to fight overfitting\n  4. LoRA r=64 (upgraded from 16/32) — more capacity\n  5. Effective batch 64 (batch=16 x grad_accum=4)\n  6. 20 epochs + SWA from epoch 5\n  7. Per-sample confidence weighting (kept from v1)\n\nScientific basis:\n  - K-fold CV: Kohavi (1995) — 5-fold has optimal bias/variance tradeoff\n  - Adversarial: Miyato et al. (2017) — Virtual Adversarial Training\n  - Mixup: Zhang et al. (2018) — mixup: Beyond Empirical Risk Minimization\n  - SWA: Izmailov et al. (2018) — Averaging Weights Leads to Wider Optima\n  - Focal Loss: Lin et al. (2017) — down-weights easy examples\n  - Label Smoothing: Szegedy et al. (2016) — prevents overconfidence\n  - Temperature: Guo et al. (2017) — calibrates softmax\n  - LoRA: Hu et al. (2021) — parameter-efficient fine-tuning\n\nUsage:\n  python finetune_v3.py --task sentiment --dataset datasets/dataset_v9.jsonl\n  python finetune_v3.py --task sentiment --kfold 5  # K-fold CV mode\n"""\nimport os\nimport json\nimport random\nimport argparse\nimport numpy as np\nimport logging\nimport logging\nfrom pathlib import Path\nlogger = logging.getLogger(__name__)\nlogger = logging.getLogger(__name__)\nfrom dataclasses import asdict\nfrom collections import Counter\n\n# v3.1: Set CUDA memory allocator config BEFORE torch import\n# Helps prevent OOM by using expandable segments (less fragmentation)\nos.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")\n\nimport torch\nimport torch.nn.functional as F\nfrom torch.utils.data import Dataset, DataLoader\nfrom transformers import (\n    AutoTokenizer, AutoModelForSequenceClassification,\n    Trainer, TrainingArguments, EarlyStoppingCallback, TrainerCallback\n)\n# v3.2: SWA (Stochastic Weight Averaging) — Izmailov et al. 2018\n# Averages model weights from SWA_START_EPOCH onwards for flatter optimum\nimport copy\nfrom peft import LoraConfig, get_peft_model, TaskType\nfrom sklearn.metrics import f1_score, accuracy_score, confusion_matrix\nfrom sklearn.model_selection import StratifiedKFold, GroupKFold\n\n# Import hyperparams\nimport sys\nsys.path.insert(0, str(Path(__file__).resolve().parent / "configs"))\nimport hyperparams_v4 as H\n\n# ---------------------------------------------------------------------------\n# 0. Reproducibility\n# ---------------------------------------------------------------------------\ntorch.manual_seed(H.SEED)\nrandom.seed(H.SEED)\nnp.random.seed(H.SEED)\n\n# ---------------------------------------------------------------------------\n# 1. Dataset\n# ---------------------------------------------------------------------------\nTASK_CFG = {\n    "relevancy": {\n        "data_file": "dataset_gold_standard_final.jsonl",\n        "label_field": "gold_relevancy",\n        "text_field": "text",\n        "entity_field": "entity_name",\n        "entity_premise_field": "entity_premise",\n        "base_model": H.RELEVANCY_BASE,\n        "labels": H.RELEVANCY_LABELS,\n        "out_dir": H.OUT_DIR_RELEVANCY,\n        "exclude_flags": ["corruption_stitch", "wrong_entity"],\n        "oversample": False,\n    },\n    "sentiment": {\n        "data_file": "dataset_gold_standard_final.jsonl",\n        "label_field": "label",\n        "text_field": "text",\n        "entity_field": "entity_name",\n        "entity_premise_field": "entity_premise",\n        "base_model": H.SENTIMENT_BASE,\n        "labels": H.SENTIMENT_LABELS,\n        "out_dir": H.OUT_DIR_SENTIMENT,\n        "exclude_flags": ["corruption_stitch", "wrong_entity"],\n        "oversample": True,\n        "filter": lambda r: r.get("gold_relevancy", "relevant") == "relevant",\n    },\n}\n\n\ndef oversample_minority(rows, targets, seed=H.SEED):\n    """Oversample minority classes to target counts via random duplication."""\n    import random as _rng\n    rng = _rng.Random(seed)\n    by_label = {}\n    for r in rows:\n        by_label.setdefault(r["label"], []).append(r)\n    result = []\n    for label, items in by_label.items():\n        target = targets.get(label, len(items))\n        pool = list(items); rng.shuffle(pool)\n        result.extend(pool)\n        needed = target - len(pool)\n        for _ in range(max(0, needed)):\n            result.append(rng.choice(pool))\n    rng.shuffle(result)\n    return result\n\n\nclass PairDataset(Dataset):\n    """Sentence-pair dataset with per-sample confidence weighting."""\n\n    def __init__(self, rows, tokenizer, label2id, max_len=H.MAX_SEQ_LENGTH):\n        self.rows = rows\n        self.tokenizer = tokenizer\n        self.label2id = label2id\n        self.max_len = max_len\n\n    def __len__(self):\n        return len(self.rows)\n\n    def __getitem__(self, idx):\n        r = self.rows[idx]\n        enc = self.tokenizer(\n            r["premise"], r["hypothesis"],\n            truncation=True, max_length=self.max_len,\n            padding="max_length", return_tensors="pt",\n        )\n        return {\n            "input_ids": enc["input_ids"][0],\n            "attention_mask": enc["attention_mask"][0],\n            "token_type_ids": enc.get("token_type_ids", torch.zeros_like(enc["input_ids"][0]))[0]\n                if self.tokenizer.model_max_length and "token_type_ids" in enc\n                else torch.zeros(self.max_len, dtype=torch.long),\n            "labels": torch.tensor(self.label2id[r["label"]], dtype=torch.long),\n            "sample_weight": torch.tensor(r.get("confidence", 0.5), dtype=torch.float),\n        }\n\n\ndef load_jsonl(path):\n    return [json.loads(l) for l in open(path) if l.strip()]\n\n\ndef stratified_split(rows, label_key, train_p, val_p, seed=H.SEED):\n    rng = random.Random(seed)\n    by_label = {}\n    for r in rows:\n        by_label.setdefault(r[label_key], []).append(r)\n    train, val, test = [], [], []\n    for lab, items in by_label.items():\n        items = list(items)\n        rng.shuffle(items)\n        n = len(items)\n        n_test = max(1, int(round(n * H.TEST_SPLIT)))\n        n_val = max(1, int(round(n * H.VAL_SPLIT)))\n        n_train = max(1, n - n_test - n_val)\n        train.extend(items[:n_train])\n        val.extend(items[n_train:n_train + n_val])\n        test.extend(items[n_train + n_val:n_train + n_val + n_test])\n    rng.shuffle(train); rng.shuffle(val); rng.shuffle(test)\n    return train, val, test\n\n\n# ---------------------------------------------------------------------------\n# 2. Class-balanced focal loss with mixup support\n# ---------------------------------------------------------------------------\ndef class_weights_from_freq(labels, num_classes, method="log"):\n    """Class reweighting. method=\'sqrt\' (Cui 2019) or \'log\' (v4, gentler)."""\n    counts = np.bincount(labels, minlength=num_classes).astype(float)\n    freq = counts / counts.sum()\n    if method == "sqrt":\n        w = 1.0 / np.sqrt(freq + 1e-8)\n    else:\n        w = 1.0 / np.log(freq + 1.0 + 1e-8)\n    w = w / w.mean()\n    return torch.tensor(w, dtype=torch.float)\n\n\ndef mixup_embeddings(embeds, labels, alpha=H.MIXUP_ALPHA):\n    """Mixup augmentation on embeddings (Zhang et al. 2018).\n\n    Returns mixed embeddings + mixed labels (soft).\n    """\n    if alpha <= 0:\n        return embeds, labels, labels, 1.0\n\n    lam = np.random.beta(alpha, alpha)\n    batch_size = embeds.size(0)\n    index = torch.randperm(batch_size, device=embeds.device)\n    mixed_embeds = lam * embeds + (1 - lam) * embeds[index]\n    return mixed_embeds, labels, labels[index], lam\n\n\nclass FocalLossTrainerV4(Trainer):\n    """v4 Trainer: Focal Loss + log class weights + per-sample confidence +\n    adversarial training + mixup."""\n\n    def __init__(self, *args, class_weights=None, focal_gamma=H.FOCAL_GAMMA,\n                 label_smoothing=H.LABEL_SMOOTHING,\n                 adversarial=H.ADVERSARIAL_ENABLED,\n                 mixup=H.MIXUP_ENABLED, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.class_weights = class_weights\n        self.focal_gamma = focal_gamma\n        self.label_smoothing = label_smoothing\n        # v3.1: Auto-disable adversarial on low-memory GPUs (< 12GB) to prevent OOM\n        if adversarial and torch.cuda.is_available():\n            gpu_mem_gb = torch.cuda.get_device_properties(0).total_mem / (1024**3)\n            if gpu_mem_gb < 12:\n                logger.warning(f"GPU memory {gpu_mem_gb:.1f}GB < 12GB — disabling adversarial training (OOM prevention)")\n                adversarial = False\n        self.adversarial = adversarial\n        self.mixup = mixup\n\n    def compute_loss(self, model, inputs, return_outputs=False, **kwargs):\n        labels = inputs.pop("labels")\n        sample_weights = inputs.pop("sample_weight", None)\n\n        # Get embeddings (for mixup + adversarial)\n        # NOTE: HuggingFace Trainer passes `model` param to compute_loss.\n        # We use `model.training` to check if we\'re in train mode.\n        is_training = model.training\n        # v3.1: NEVER use output_hidden_states=True (saves ~2.8GB GPU memory)\n        # Adversarial training uses model.get_input_embeddings() directly,\n        # NOT output_hidden_states — so we don\'t need it at all.\n        outputs = model(**inputs)\n        logits = outputs.logits\n        probs = F.softmax(logits, dim=-1)\n\n        # Mixup on logits (simpler than embedding-level)\n        if self.mixup and is_training and random.random() < H.MIXUP_PROB:\n            lam = np.random.beta(H.MIXUP_ALPHA, H.MIXUP_ALPHA)\n            batch_size = logits.size(0)\n            index = torch.randperm(batch_size, device=logits.device)\n            mixed_logits = lam * logits + (1 - lam) * logits[index]\n            mixed_labels = labels[index]\n\n            # Soft labels for mixup\n            onehot_orig = F.one_hot(labels, num_classes=logits.size(-1)).float()\n            onehot_mixed = F.one_hot(mixed_labels, num_classes=logits.size(-1)).float()\n            soft_labels = lam * onehot_orig + (1 - lam) * onehot_mixed\n            soft_labels = (1 - self.label_smoothing) * soft_labels + \\\n                          self.label_smoothing / logits.size(-1)\n\n            log_probs = F.log_softmax(mixed_logits, dim=-1)\n            ce = -(soft_labels * log_probs).sum(dim=-1)\n            pt = probs.gather(1, labels.unsqueeze(1)).squeeze(1).clamp(min=1e-8)\n            focal = (1.0 - pt) ** self.focal_gamma\n            per_sample = focal * ce\n        else:\n            # Standard focal loss with label smoothing\n            pt = probs.gather(1, labels.unsqueeze(1)).squeeze(1).clamp(min=1e-8)\n            focal = (1.0 - pt) ** self.focal_gamma\n            ce = F.cross_entropy(logits, labels, weight=self.class_weights.to(logits.device),\n                                  label_smoothing=self.label_smoothing, reduction="none")\n            per_sample = focal * ce\n\n        # Per-sample confidence weighting\n        if sample_weights is not None:\n            per_sample = per_sample * sample_weights.to(logits.device)\n\n        loss = per_sample.mean()\n\n        # Adversarial training (PGD on embeddings)\n        if self.adversarial and is_training:\n            adv_loss = self._adversarial_loss(model, inputs, labels, sample_weights)\n            loss = loss + H.ADVERSARIAL_ALPHA * adv_loss\n\n        return (loss, outputs) if return_outputs else loss\n\n# ---------------------------------------------------------------------------\n# v3.2: SWA (Stochastic Weight Averaging) Callback\n# ---------------------------------------------------------------------------\nclass SWACallback(TrainerCallback):\n    """Averages LoRA weights from SWA_START_EPOCH for flatter optimum.\n    \n    Paper: Izmailov et al. (2018) "Averaging Weights Leads to Wider Optima"\n    Expected: +1-2% F1, better generalization on small datasets.\n    """\n    def __init__(self, start_epoch=5, anneal_epochs=3):\n        self.start_epoch = start_epoch\n        self.anneal_epochs = anneal_epochs\n        self.swa_weights = None\n        self.swa_count = 0\n        self.n_averaged = 0\n\n    def on_epoch_end(self, args, state, control, model=None, **kwargs):\n        current_epoch = int(state.epoch)\n        if current_epoch < self.start_epoch:\n            return\n\n        # Get LoRA parameters (only adapter weights, not frozen base)\n        lora_params = {n: p.detach().clone() for n, p in model.named_parameters() if \'lora_\' in n.lower()}\n\n        if self.swa_weights is None:\n            # First SWA epoch — initialize\n            self.swa_weights = lora_params\n            self.n_averaged = 1\n        else:\n            # Running average: swa = (swa * n + new) / (n + 1)\n            for n in lora_params:\n                self.swa_weights[n] = (\n                    self.swa_weights[n] * self.n_averaged + lora_params[n]\n                ) / (self.n_averaged + 1)\n            self.n_averaged += 1\n\n        logger.info(f"  [SWA] Epoch {current_epoch}: averaged {self.n_averaged} weight snapshots")\n\n    def on_train_end(self, args, state, control, model=None, **kwargs):\n        """Apply SWA weights to model at end of training."""\n        if self.swa_weights is None or self.n_averaged < 2:\n            return\n\n        # Replace LoRA weights with SWA-averaged version\n        with torch.no_grad():\n            for n, p in model.named_parameters():\n                if n in self.swa_weights:\n                    p.copy_(self.swa_weights[n])\n\n        logger.info(f"  [SWA] Applied {self.n_averaged}-epoch weight average to model")\n\n\n    def _adversarial_loss(self, model, inputs, labels, sample_weights):\n        """PGD adversarial perturbation on input_ids embeddings (Miyato et al. 2017)."""\n        try:\n            # Get embedding layer\n            embed_layer = model.get_input_embeddings()\n            input_ids = inputs["input_ids"]\n\n            # Get embeddings (require grad)\n            embeds = embed_layer(input_ids)\n            embeds = embeds.detach().requires_grad_(True)\n\n            # Forward with perturbed embeddings\n            with torch.enable_grad():\n                # Replace input_ids with embeddings in forward\n                inputs_adv = {k: v for k, v in inputs.items() if k != "input_ids"}\n                inputs_adv["inputs_embeds"] = embeds\n                outputs_adv = model(**inputs_adv)\n                logits_adv = outputs_adv.logits\n                probs_adv = F.softmax(logits_adv, dim=-1)\n                pt_adv = probs_adv.gather(1, labels.unsqueeze(1)).squeeze(1).clamp(min=1e-8)\n                focal_adv = (1.0 - pt_adv) ** self.focal_gamma\n                ce_adv = F.cross_entropy(logits_adv, labels,\n                                          weight=self.class_weights.to(logits_adv.device),\n                                          label_smoothing=self.label_smoothing, reduction="none")\n                loss_adv = (focal_adv * ce_adv).mean()\n\n            # Compute gradient\n            grad = torch.autograd.grad(loss_adv, embeds)[0]\n            # PGD perturbation\n            perturb = H.ADVERSARIAL_EPSILON * grad.sign()\n            embeds_perturbed = embeds + perturb\n\n            # Forward with perturbed embeddings\n            inputs_pert = {k: v for k, v in inputs.items() if k != "input_ids"}\n            inputs_pert["inputs_embeds"] = embeds_perturbed.detach()\n            outputs_pert = model(**inputs_pert)\n            logits_pert = outputs_pert.logits\n            probs_pert = F.softmax(logits_pert, dim=-1)\n            pt_pert = probs_pert.gather(1, labels.unsqueeze(1)).squeeze(1).clamp(min=1e-8)\n            focal_pert = (1.0 - pt_pert) ** self.focal_gamma\n            ce_pert = F.cross_entropy(logits_pert, labels,\n                                       weight=self.class_weights.to(logits_pert.device),\n                                       label_smoothing=self.label_smoothing, reduction="none")\n            per_sample_pert = focal_pert * ce_pert\n            if sample_weights is not None:\n                per_sample_pert = per_sample_pert * sample_weights.to(logits_pert.device)\n            return per_sample_pert.mean()\n        except Exception as e:\n            # Adversarial training can fail on some model architectures — skip gracefully\n            return torch.tensor(0.0, device=labels.device)\n\n\n# ---------------------------------------------------------------------------\n# 3. Temperature scaling (Guo et al. 2017)\n# ---------------------------------------------------------------------------\n@torch.no_grad()\ndef calibrate_temperature(model, val_ds, tokenizer, device=None):\n    if device is None:\n        device = "cuda" if torch.cuda.is_available() else "cpu"\n    model.eval().to(device)\n    logits_all, labels_all = [], []\n    for i in range(len(val_ds)):\n        item = {k: v.unsqueeze(0).to(device) for k, v in val_ds[i].items()}\n        labels_all.append(int(item.pop("labels").item()))\n        out = model(**item)\n        logits_all.append(out.logits.squeeze(0).cpu())\n    logits = torch.stack(logits_all)\n    labels = torch.tensor(labels_all)\n\n    T = torch.ones(1, requires_grad=True)\n    opt = torch.optim.LBFGS([T], lr=0.1, max_iter=50)\n    def closure():\n        opt.zero_grad()\n        loss = F.cross_entropy(logits / T, labels)\n        loss.backward()\n        return loss\n    opt.step(closure)\n    return float(T.clamp(0.05, 10.0).item())\n\n\n# ---------------------------------------------------------------------------\n# 4. K-Fold Cross-Validation\n# ---------------------------------------------------------------------------\ndef run_kfold(task, all_rows, label2id, id2label, k=H.K_FOLD_N):\n    """Run entity-aware K-fold CV. Uses GroupKFold by entity to prevent leakage."""\n    print(f"\\n{\'=\'*70}")\n    print(f"K-FOLD CV (entity-aware, k={k})")\n    print(f"{\'=\'*70}")\n\n    labels_array = np.array([label2id[r["label"]] for r in all_rows])\n    groups = [r.get("entity", r.get("entity_name", "unknown")) for r in all_rows]\n    n_entities = len(set(groups))\n    print(f"  Rows: {len(all_rows)}, Unique entities: {n_entities}")\n\n    # Use GroupKFold if enough entities, else StratifiedKFold\n    if n_entities >= k * 3:\n        gkf = GroupKFold(n_splits=k)\n        splits = gkf.split(np.zeros(len(all_rows)), labels_array, groups)\n    else:\n        print(f"  Warning: too few entities for GroupKFold, using StratifiedKFold")\n        skf = StratifiedKFold(n_splits=k, shuffle=True, random_state=H.SEED)\n        splits = skf.split(np.zeros(len(all_rows)), labels_array)\n\n    cfg = TASK_CFG[task]\n    fold_results = []\n    for fold, (train_idx, val_idx) in enumerate(splits):\n        print(f"\\n--- Fold {fold+1}/{k} ---")\n        train_rows = [all_rows[i] for i in train_idx]\n        val_rows = [all_rows[i] for i in val_idx]\n\n        # v4: Oversample training set only\n        if H.OVERSAMPLING_ENABLED and cfg.get("oversample"):\n            print(f"  Oversampling train: {len(train_rows)} -> ", end="")\n            train_rows = oversample_minority(train_rows, H.OVERSAMPLING_TARGETS, seed=H.SEED + fold)\n            print(f"{len(train_rows)}")\n\n        print(f"  train: {len(train_rows)} | val: {len(val_rows)}")\n        print(f"  train balance: {dict(Counter(r[\'label\'] for r in train_rows))}")\n        print(f"  val   balance: {dict(Counter(r[\'label\'] for r in val_rows))}")\n\n        metrics = train_single_fold(task, train_rows, val_rows, label2id, id2label,\n                                     out_suffix=f"_fold{fold+1}")\n        fold_results.append(metrics)\n        print(f"  metrics: {metrics}")\n\n    # v3.1: Clear GPU memory after each fold\n    import gc\n    gc.collect()\n    torch.cuda.empty_cache()\n\n    # Aggregate\n    print(f"\\n{\'=\'*70}")\n    print(f"K-FOLD RESULTS (k={k})")\n    print(f"{\'=\'*70}")\n    avg_metrics = {}\n    for key in fold_results[0]:\n        if isinstance(fold_results[0][key], (int, float)):\n            values = [r[key] for r in fold_results]\n            avg = np.mean(values)\n            std = np.std(values)\n            avg_metrics[key] = {"mean": avg, "std": std, "values": values}\n            print(f"  {key:20s}: {avg:.4f} ± {std:.4f}")\n\n    return {"folds": fold_results, "aggregate": avg_metrics}\n\n\n# ---------------------------------------------------------------------------\n# 5. Single fold training\n# ---------------------------------------------------------------------------\ndef train_single_fold(task, train_rows, val_rows, label2id, id2label,\n                       out_suffix=""):\n    cfg = TASK_CFG[task]\n    out_dir = Path(cfg["out_dir"])\n    out_dir.mkdir(parents=True, exist_ok=True)\n\n    tok = AutoTokenizer.from_pretrained(cfg["base_model"])\n    model = AutoModelForSequenceClassification.from_pretrained(\n        cfg["base_model"], num_labels=len(cfg["labels"]),\n        id2label=id2label, label2id=label2id,\n        ignore_mismatched_sizes=True,\n    )\n\n    lora_cfg = LoraConfig(\n        r=H.LORA.r, lora_alpha=H.LORA.alpha, lora_dropout=H.LORA.dropout,\n        bias=H.LORA.bias, task_type=TaskType.SEQ_CLS,\n        target_modules=H.LORA.target_modules,\n    )\n    model = get_peft_model(model, lora_cfg)\n    if not out_suffix:\n        model.print_trainable_parameters()\n\n    # Class weights\n    train_label_ids = [label2id[r["label"]] for r in train_rows]\n    cw = class_weights_from_freq(train_label_ids, len(cfg["labels"]))\n\n    # Datasets\n    train_ds = PairDataset(train_rows, tok, label2id)\n    val_ds = PairDataset(val_rows, tok, label2id)\n\n    steps_per_epoch = max(1, len(train_ds) // (H.BATCH_SIZE * H.GRAD_ACCUM_STEPS))\n    warmup_steps = int(H.WARMUP_RATIO * steps_per_epoch * H.NUM_EPOCHS)\n\n    # Build TrainingArguments dict (compatible with transformers 4.40+)\n    train_args_dict = dict(\n        output_dir=str(out_dir),\n        num_train_epochs=H.NUM_EPOCHS,\n        per_device_train_batch_size=H.BATCH_SIZE,\n        per_device_eval_batch_size=H.BATCH_SIZE,  # v3.1: reduced from *2 (OOM fix)\n        # v3.1: OOM prevention settings\n        dataloader_pin_memory=False,  # saves pinned memory\n        gradient_checkpointing=False,\n        gradient_accumulation_steps=H.GRAD_ACCUM_STEPS,\n        learning_rate=H.LEARNING_RATE,\n        weight_decay=H.WEIGHT_DECAY,\n        adam_beta1=H.ADAM_BETA1, adam_beta2=H.ADAM_BETA2, adam_epsilon=H.ADAM_EPSILON,\n        max_grad_norm=H.MAX_GRAD_NORM,\n        warmup_steps=warmup_steps,\n        lr_scheduler_type=H.SCHEDULER,\n        # v3.2: pass num_cycles for cosine_with_restarts\n        lr_scheduler_kwargs={"num_cycles": H.SCHEDULER_NUM_CYCLES} if H.SCHEDULER == "cosine_with_restarts" else None,\n        fp16=H.FP16,\n        save_strategy="epoch",\n        save_total_limit=1,\n        load_best_model_at_end=True,\n        metric_for_best_model="eval_macro_f1",  # v3.2: full key for transformers 5.x\n        greater_is_better=True,\n        seed=H.SEED,\n        report_to="none",\n        logging_steps=max(1, steps_per_epoch // 4),\n    )\n    # eval_strategy: renamed in 4.46+ (try new name, fallback to old)\n    try:\n        train_args_dict["eval_strategy"] = "epoch"\n        targs = TrainingArguments(**train_args_dict)\n    except TypeError:\n        # Old transformers (< 4.46) uses evaluation_strategy\n        train_args_dict["evaluation_strategy"] = "epoch"\n        targs = TrainingArguments(**train_args_dict)\n\n    def compute_metrics(eval_pred):\n        logits, labels = eval_pred\n        preds = np.argmax(logits, axis=-1)\n        return {\n            "accuracy": accuracy_score(labels, preds),\n            "macro_f1": f1_score(labels, preds, average="macro"),\n            "weighted_f1": f1_score(labels, preds, average="weighted"),\n        }\n\n    trainer = FocalLossTrainerV4(\n        model=model,\n        args=targs,\n        train_dataset=train_ds,\n        eval_dataset=val_ds,\n        processing_class=tok,\n        compute_metrics=compute_metrics,\n        class_weights=cw,\n        focal_gamma=H.FOCAL_GAMMA,\n        adversarial=H.ADVERSARIAL_ENABLED,\n        mixup=H.MIXUP_ENABLED,\n        callbacks=[\n            EarlyStoppingCallback(early_stopping_patience=H.EARLY_STOP_PATIENCE),\n        ] + ([SWACallback(start_epoch=H.SWA_START_EPOCH, anneal_epochs=H.SWA_ANNEAL_EPOCHS)]\n             if H.SWA_ENABLED else []),\n    )\n\n    trainer.train()\n    # v3.1: Clear cache before eval to prevent OOM\n    import gc\n    gc.collect()\n    torch.cuda.empty_cache()\n    val_metrics = trainer.evaluate(val_ds, metric_key_prefix="val")\n\n    # Temperature calibration\n    T = calibrate_temperature(model, val_ds, tok)\n\n    # Save (only for non-K-fold mode)\n    if not out_suffix:\n        model.save_pretrained(out_dir / "lora")\n        tok.save_pretrained(out_dir / "tokenizer")\n        with open(out_dir / "metrics.json", "w") as f:\n            json.dump({\n                "task": task,\n                "val_metrics": val_metrics,\n                "temperature": T,\n                "hyperparams": {k: asdict(v) if hasattr(v, \'__dataclass_fields__\') else v\n                                for k, v in vars(H).items() if k.isupper()},\n                "train_size": len(train_rows),\n                "val_size": len(val_rows),\n                "class_weights": dict(zip(cfg[\'labels\'], cw.tolist())),\n            }, f, indent=2)\n        print(f"\\nSaved LoRA adapter + metrics -> {out_dir}")\n\n    return {\n        "accuracy": float(val_metrics.get("val_accuracy", 0)),\n        "macro_f1": float(val_metrics.get("val_macro_f1", 0)),\n        "weighted_f1": float(val_metrics.get("val_weighted_f1", 0)),\n        "temperature": T,\n    }\n\n\n# ---------------------------------------------------------------------------\n# 6. Main\n# ---------------------------------------------------------------------------\ndef main(task: str, kfold: int = 0, dataset: str = None):\n    cfg = TASK_CFG[task]\n    print(f"\\n{\'=\'*70}")\n    print(f"FINETUNE v3 TASK: {task}")\n    print(f"base: {cfg[\'base_model\']}")\n    print(f"out:  {cfg[\'out_dir\']}")\n    print(f"{\'=\'*70}\\n")\n\n    # Load dataset\n    data_path = Path(__file__).resolve().parent / "datasets" / (dataset or cfg["data_file"])\n    all_rows = load_jsonl(str(data_path))\n    print(f"Loaded {len(all_rows)} rows from {cfg[\'data_file\']}")\n\n    label2id = {l: i for i, l in enumerate(cfg["labels"])}\n    id2label = {i: l for l, i in label2id.items()}\n    label_field = cfg.get("label_field", "label")\n    exclude_flags = cfg.get("exclude_flags", [])\n    filter_fn = cfg.get("filter")\n\n    # v4: Normalize rows — handle gold standard field names\n    text_field = cfg.get("text_field", "text")\n    entity_field = cfg.get("entity_field", "entity_name")\n    entity_premise_field = cfg.get("entity_premise_field", "entity_premise")\n    rows = []\n    excluded = {"bad_flag": 0, "filter": 0, "no_label": 0, "no_text": 0}\n    for r in all_rows:\n        if r.get("context_flag") in exclude_flags:\n            excluded["bad_flag"] += 1\n            continue\n        label = r.get(label_field) or r.get("gold_label") or r.get("pseudo_label")\n        if not label or label not in label2id:\n            excluded["no_label"] += 1\n            continue\n        text = r.get(text_field) or r.get("context_text") or r.get("hypothesis", "")\n        if not text or len(text.strip()) < 10:\n            excluded["no_text"] += 1\n            continue\n        if filter_fn and not filter_fn(r):\n            excluded["filter"] += 1\n            continue\n        entity = r.get(entity_field, "")\n        premise = r.get(entity_premise_field) or f"Tentang {entity}" or entity\n        rows.append({\n            "premise": premise,\n            "hypothesis": text,\n            "label": label,\n            "confidence": r.get("label_confidence", 0.5),\n            "label_source": r.get("label_source", "unknown"),\n            "entity": entity,\n        })\n    print(f"After filter: {len(rows)} rows (excluded: {excluded})")\n\n    if kfold > 1:\n        # K-fold mode\n        results = run_kfold(task, rows, label2id, id2label, k=kfold)\n        out_dir = Path(cfg["out_dir"])\n        out_dir.mkdir(parents=True, exist_ok=True)\n        with open(out_dir / "kfold_results.json", "w") as f:\n            json.dump(results, f, indent=2)\n        print(f"\\nK-fold results saved -> {out_dir / \'kfold_results.json\'}")\n    else:\n        # Single train/val/test split\n        train_rows, val_rows, test_rows = stratified_split(rows, "label", H.TRAIN_SPLIT, H.VAL_SPLIT)\n        # v4: Oversample training set\n        if H.OVERSAMPLING_ENABLED and cfg.get("oversample"):\n            print(f"Oversampling train: {len(train_rows)} -> ", end="")\n            train_rows = oversample_minority(train_rows, H.OVERSAMPLING_TARGETS, seed=H.SEED)\n            print(f"{len(train_rows)}")\n        print(f"Split: train={len(train_rows)} val={len(val_rows)} test={len(test_rows)}")\n        print(f"Train class balance: {dict(Counter(r[\'label\'] for r in train_rows))}")\n        print(f"Val   class balance: {dict(Counter(r[\'label\'] for r in val_rows))}")\n        print(f"Test  class balance: {dict(Counter(r[\'label\'] for r in test_rows))}")\n\n        metrics = train_single_fold(task, train_rows, val_rows, label2id, id2label)\n        print(f"\\nFinal metrics: {metrics}")\n\n\nif __name__ == "__main__":\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--task", choices=["relevancy", "sentiment"], required=True)\n    ap.add_argument("--dataset", default=None, help="Override dataset file")\n    ap.add_argument("--kfold", type=int, default=0,\n                    help="K-fold CV (0=disabled, 5=recommended)")\n    args = ap.parse_args()\n    main(args.task, kfold=args.kfold, dataset=args.dataset)\n',
    'evaluate_v4.py': '"""\nevaluate.py\n===========\nEvaluation + the confidence-threshold sweep that produces the ≥97% kept-accuracy\ncurve promised in CRITICAL_ANALYSIS.md §7.1.\n\nEffectiveAccuracy = |{x in K : pred(x)=y(x)}| / |K|      (kept-set accuracy)\nCoverage          = |K| / N                                (fraction not deferred)\n\nwhere K = {x : max_softmax(p(x)) >= tau}.\n\nRun after finetune.py:\n    python evaluate.py --task sentiment --run-dir ./runs/sentiment\n    python evaluate.py --task relevancy --run-dir ./runs/relevancy\n"""\nfrom __future__ import annotations\nimport json, argparse, math\nfrom pathlib import Path\nfrom collections import Counter\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom transformers import AutoTokenizer, AutoModelForSequenceClassification\nfrom peft import PeftModel\nfrom sklearn.metrics import f1_score, accuracy_score, confusion_matrix, classification_report\n\nimport hyperparams_v4 as H\n\nTASK_CFG = {\n    "relevancy": {"labels": H.RELEVANCY_LABELS, "data": "dataset_gold_standard_final.jsonl"},\n    "sentiment": {"labels": H.SENTIMENT_LABELS, "data": "dataset_gold_standard_final.jsonl"},\n}\n\ndef load_jsonl(p):\n    return [json.loads(l) for l in open(p) if l.strip()]\n\ndef stratified_split(rows, seed=H.SEED):\n    import random\n    rng = random.Random(seed)\n    by = {}\n    for r in rows: by.setdefault(r["label"], []).append(r)\n    tr, va, te = [], [], []\n    for lab, items in by.items():\n        items = list(items); rng.shuffle(items)\n        n = len(items)\n        nt = max(1, int(round(n*H.TEST_SPLIT)))\n        nv = max(1, int(round(n*H.VAL_SPLIT)))\n        ntr = max(1, n - nt - nv)\n        tr.extend(items[:ntr]); va.extend(items[ntr:ntr+nv]); te.extend(items[ntr+nv:])\n    rng.shuffle(tr); rng.shuffle(va); rng.shuffle(te)\n    return tr, va, te\n\n@torch.no_grad()\ndef score_all(model, tok, rows, labels, device=None, max_len=H.MAX_SEQ_LENGTH):\n    if device is None:\n        device = "cuda" if torch.cuda.is_available() else "cpu"\n    model.eval().to(device)\n    label2id = {l:i for i,l in enumerate(labels)}\n    probs, golds = [], []\n    for r in rows:\n        enc = tok(r["premise"], r["hypothesis"], truncation=True,\n                  max_length=max_len, return_tensors="pt").to(device)\n        out = model(**enc)\n        p = F.softmax(out.logits / 1.0, dim=-1)[0].cpu().numpy()\n        probs.append(p)\n        golds.append(label2id[r["label"]])\n    return np.array(probs), np.array(golds)\n\ndef apply_temperature(probs, T):\n    # re-softmax with temperature on logits: but we only have probs.\n    # Approximate by sharpening: p\' = p^(1/T) / sum. Valid for calibration\n    # comparison; for exact, re-run score_all with T. We re-run instead.\n    return probs  # placeholder; real T applied in score_all via logits/T\n\n@torch.no_grad()\ndef score_all_calibrated(model, tok, rows, labels, T, device=None, max_len=H.MAX_SEQ_LENGTH):\n    """Score with temperature scaling on logits."""\n    if device is None:\n        device = "cuda" if torch.cuda.is_available() else "cpu"\n    model.eval().to(device)\n    label2id = {l:i for i,l in enumerate(labels)}\n    probs, golds = [], []\n    for r in rows:\n        enc = tok(r["premise"], r["hypothesis"], truncation=True,\n                  max_length=max_len, return_tensors="pt").to(device)\n        out = model(**enc)\n        p = F.softmax(out.logits / T, dim=-1)[0].cpu().numpy()\n        probs.append(p)\n        golds.append(label2id[r["label"]])\n    return np.array(probs), np.array(golds)\n\ndef confidence_threshold_sweep(probs, golds, taus=None):\n    """Return list of (tau, kept_acc, coverage, macro_f1_kept, n_kept, n_deferred)."""\n    if taus is None:\n        taus = np.arange(0.30, 0.98, 0.03)\n    preds = probs.argmax(axis=1)\n    confs = probs.max(axis=1)\n    rows = []\n    for tau in taus:\n        keep = confs >= tau\n        n_kept = int(keep.sum())\n        n_def = int((~keep).sum())\n        if n_kept == 0:\n            continue\n        kept_acc = accuracy_score(golds[keep], preds[keep])\n        kept_f1 = f1_score(golds[keep], preds[keep], average="macro",\n                           labels=list(range(probs.shape[1])), zero_division=0)\n        rows.append({\n            "tau": round(float(tau), 3),\n            "kept_accuracy": round(float(kept_acc), 4),\n            "coverage": round(n_kept / len(golds), 4),\n            "kept_macro_f1": round(float(kept_f1), 4),\n            "n_kept": n_kept,\n            "n_deferred": n_def,\n        })\n    return rows\n\ndef main(task, run_dir):\n    cfg = TASK_CFG[task]\n    run_dir = Path(run_dir)\n    metrics_path = run_dir / "metrics.json"\n    metrics = json.load(open(metrics_path)) if metrics_path.exists() else {}\n    T = metrics.get("temperature", 1.0)\n    print(f"Task: {task} | run_dir: {run_dir} | temperature: {T}")\n\n    # load base + LoRA\n    base = cfg["base_model"] if task == "sentiment" else H.RELEVANCY_BASE\n    tok = AutoTokenizer.from_pretrained(run_dir / "tokenizer")\n    model = AutoModelForSequenceClassification.from_pretrained(base)\n    model = PeftModel.from_pretrained(model, run_dir / "lora")\n    model = model.merge_and_unload()  # merge LoRA for faster inference\n\n    # data — reproduce the SAME stratified test split as finetune.py\n    rows = load_jsonl(cfg["data"])\n    _, _, test = stratified_split(rows)\n    print(f"Test set: {len(test)} rows | balance: {dict(Counter(r[\'label\'] for r in test))}")\n\n    # score (calibrated)\n    probs, golds = score_all_calibrated(model, tok, test, cfg["labels"], T)\n\n    # full-coverage metrics\n    preds = probs.argmax(axis=1)\n    full_acc = accuracy_score(golds, preds)\n    full_f1 = f1_score(golds, preds, average="macro",\n                       labels=list(range(len(cfg["labels"]))), zero_division=0)\n    cm = confusion_matrix(golds, preds, labels=list(range(len(cfg["labels"]))))\n    print("\\n=== FULL-COVERAGE METRICS (no deferral) ===")\n    print(f"  accuracy : {full_acc:.4f}")\n    print(f"  macro-F1 : {full_f1:.4f}")\n    print(f"  confusion matrix (rows=true, cols=pred):")\n    print(f"    labels: {cfg[\'labels\']}")\n    print(f"    {cm.tolist()}")\n    print(classification_report(golds, preds, target_names=cfg["labels"], zero_division=0))\n\n    # confidence-threshold sweep\n    sweep = confidence_threshold_sweep(probs, golds)\n    print("\\n=== CONFIDENCE-THRESHOLD SWEEP (kept-set accuracy vs coverage) ===")\n    print(f"  {\'tau\':>5} {\'kept_acc\':>9} {\'coverage\':>9} {\'kept_F1\':>8} {\'kept\':>5} {\'defer\':>6}")\n    for s in sweep:\n        flag = "  <-- 97% target" if s["kept_accuracy"] >= 0.97 else ""\n        print(f"  {s[\'tau\']:>5} {s[\'kept_accuracy\']:>9.4f} {s[\'coverage\']:>9.4f} "\n              f"{s[\'kept_macro_f1\']:>8.4f} {s[\'n_kept\']:>5} {s[\'n_deferred\']:>6}{flag}")\n\n    # find the tau that hits >=97% with max coverage\n    hits_97 = [s for s in sweep if s["kept_accuracy"] >= 0.97]\n    best = max(hits_97, key=lambda s: s["coverage"]) if hits_97 else None\n    if best:\n        print(f"\\n>> >=97% kept-accuracy ACHIEVED at tau={best[\'tau\']} "\n              f"with coverage={best[\'coverage\']:.1%} ({best[\'n_kept\']}/{len(test)} kept, "\n              f"{best[\'n_deferred\']} deferred to human/LLM).")\n    else:\n        max_acc = max(s["kept_accuracy"] for s in sweep)\n        print(f"\\n>> 97% NOT reached on this test split. Max kept-acc={max_acc:.4f}.")\n        print("   Options: (a) label more gold data, (b) raise tau, (c) add the LLM second-pass for deferred.")\n\n    # save\n    out = {\n        "task": task,\n        "temperature": T,\n        "full_coverage": {"accuracy": full_acc, "macro_f1": full_f1,\n                          "confusion_matrix": cm.tolist(), "labels": cfg["labels"]},\n        "sweep": sweep,\n        "best_97": best,\n    }\n    with open(run_dir / "evaluation.json", "w") as f:\n        json.dump(out, f, indent=2)\n    print(f"\\nSaved -> {run_dir / \'evaluation.json\'}")\n\nif __name__ == "__main__":\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--task", choices=["relevancy", "sentiment"], required=True)\n    ap.add_argument("--run-dir", required=True)\n    a = ap.parse_args()\n    main(a.task, a.run_dir)\n',
    'hyperparams_v4.py': '"""\nhyperparams_v4.py\n=================\nv4 HYPERPARAMS — TUNED for gold standard dataset (~2,200 rows, LLM-verified).\n\nKey UPGRADES over v3:\n  1. Oversampling: negative → ~400, positive → ~600 (reduces imbalance)\n  2. Focal gamma: 2.5 → 3.0 (stronger focus on minority)\n  3. LoRA dropout: 0.15 → 0.20 (more regularization)\n  4. Mixup alpha: 0.2 → 0.3, prob: 30% → 40%\n  5. Label smoothing: 0.05 → 0.07\n  6. Class weights: 1/sqrt(freq) → 1/log(freq+1) (gentler)\n  7. Entity-stratified K-fold (GroupKFold by entity)\n  8. Epochs: 20 → 18, SWA start: 5 → 4\n"""\nfrom dataclasses import dataclass\n\nRELEVANCY_BASE = "apriandito/indobert-relevancy-classifier"\nSENTIMENT_BASE = "apriandito/indobert-sentiment-classifier"\nFALLBACK_BASE  = "taufiqdp/indonesian-sentiment"\n\nMAX_SEQ_LENGTH = 256\nPAIR_FORMAT    = True\n\n@dataclass\nclass LoRAConfig:\n    r: int = 64\n    alpha: int = 128\n    dropout: float = 0.20\n    bias: str = "none"\n    task_type = "SEQ_CLS"\n    target_modules = ["query", "key", "value", "dense"]\n    target_modules_extended = ["query", "key", "value", "dense", "intermediate.dense"]\n\nLORA = LoRAConfig()\n\nLEARNING_RATE = 2.5e-5\nWEIGHT_DECAY  = 0.03\nADAM_EPSILON  = 1e-8\nADAM_BETA1    = 0.9\nADAM_BETA2    = 0.999\nMAX_GRAD_NORM = 1.0\n\nWARMUP_RATIO  = 0.06\nSCHEDULER     = "cosine_with_restarts"\nSCHEDULER_NUM_CYCLES = 2\n\nBATCH_SIZE        = 8\nGRAD_ACCUM_STEPS  = 8\nNUM_EPOCHS        = 18\nEARLY_STOP_PATIENCE = 5\n\nFOCAL_GAMMA     = 3.0\nLABEL_SMOOTHING = 0.07\nCLASS_WEIGHT_FN  = "log"\n\nSWA_ENABLED       = True\nSWA_START_EPOCH   = 4\nSWA_LR            = 5e-6\nSWA_ANNEAL_EPOCHS = 3\n\nADVERSARIAL_ENABLED = True\nADVERSARIAL_EPSILON = 1e-5\nADVERSARIAL_ALPHA   = 0.5\n\nMIXUP_ENABLED = True\nMIXUP_ALPHA   = 0.3\nMIXUP_PROB    = 0.4\n\nOVERSAMPLING_ENABLED = True\nOVERSAMPLING_TARGETS = {"negative": 400, "positive": 600}\n\nK_FOLD_ENABLED = True\nK_FOLD_N       = 5\nK_FOLD_STRATIFIED = True\nK_FOLD_ENTITY_AWARE = True\n\nVAL_SPLIT   = 0.15\nTEST_SPLIT  = 0.15\nTRAIN_SPLIT = 1.0 - VAL_SPLIT - TEST_SPLIT\nSEED        = 42\n\nSENTIMENT_LABELS = ["negative", "neutral", "positive"]\nRELEVANCY_LABELS = ["not_relevant", "relevant"]\n\nTEMPERATURE    = 1.3\nCONFIDENCE_TAU = 0.70\n\nOUT_DIR_RELEVANCY = "./runs/relevancy_v4"\nOUT_DIR_SENTIMENT = "./runs/sentiment_v4"\n\nHF_ORG          = "raynzz455"\nHF_MODEL_PREFIX = "id-political-sentiment"\nHF_SENTIMENT_MODEL = f"{HF_ORG}/{HF_MODEL_PREFIX}-sentiment-v4"\nHF_RELEVANCY_MODEL = f"{HF_ORG}/{HF_MODEL_PREFIX}-relevancy-v4"\n\nDETERMINISTIC = True\nFP16          = True\n\nMETHOD_DESCRIPTION = """\nv4: Based on gold standard dataset (~2,200 rows, LLM-verified + re-verified)\n  + Oversampling, Focal gamma=3.0, Entity-stratified K-fold\n  + Mixup 0.3/40%, Label smoothing 0.07, Log class weights\nExpected: macro-F1 0.70 → 0.75+, negative recall 0.45 → 0.60+\n"""\n',
    'sentiment_model_v6.py': '"""\nsentiment_model_v6.py\n=====================\nv6 Production inference model — loads v4 LoRA adapter + temperature calibration.\n\nFeatures: LoRA adapter loading, temperature scaling, confidence-threshold deferral,\nbatch inference, sentence-pair format (entity + context).\n"""\nimport json, logging\nfrom pathlib import Path\nfrom typing import List, Dict, Optional, Tuple\nimport torch\nimport torch.nn.functional as F\nfrom transformers import AutoTokenizer, AutoModelForSequenceClassification\nfrom peft import PeftModel\n\nlogger = logging.getLogger(__name__)\n\nDEFAULT_BASE_MODEL = "apriandito/indobert-sentiment-classifier"\nDEFAULT_MAX_SEQ_LENGTH = 256\nDEFAULT_TEMPERATURE = 1.3\nDEFAULT_CONFIDENCE_TAU = 0.70\nSENTIMENT_LABELS = ["negative", "neutral", "positive"]\nLABEL_ID = {l: i for i, l in enumerate(SENTIMENT_LABELS)}\nID_LABEL = {i: l for l, i in LABEL_ID.items()}\n\n\nclass SentimentModelV6:\n    """Production sentiment classifier with v4 LoRA adapter + calibration."""\n\n    def __init__(self, adapter_path, base_model=DEFAULT_BASE_MODEL,\n                 max_seq_length=DEFAULT_MAX_SEQ_LENGTH, temperature=DEFAULT_TEMPERATURE,\n                 confidence_tau=DEFAULT_CONFIDENCE_TAU, device=None, merge_adapter=True):\n        self.max_seq_length = max_seq_length\n        self.temperature = temperature\n        self.confidence_tau = confidence_tau\n        self.adapter_path = adapter_path\n        if device is None: device = "cuda" if torch.cuda.is_available() else "cpu"\n        self.device = torch.device(device)\n        logger.info(f"Using device: {self.device}")\n\n        self.tokenizer = AutoTokenizer.from_pretrained(base_model)\n        base = AutoModelForSequenceClassification.from_pretrained(base_model, num_labels=len(SENTIMENT_LABELS))\n        self.model = PeftModel.from_pretrained(base, str(adapter_path))\n        if merge_adapter and hasattr(self.model, \'merge_and_unload\'):\n            self.model = self.model.merge_and_unload()\n            logger.info("LoRA adapter merged")\n        self.model.to(self.device)\n        self.model.eval()\n        logger.info(f"Model ready. T={temperature}, tau={confidence_tau}")\n\n    def predict(self, entity, context, return_all=False):\n        return self.predict_batch([(entity, context)], return_all=return_all)[0]\n\n    def predict_batch(self, items, return_all=False, batch_size=32):\n        all_results = []\n        for i in range(0, len(items), batch_size):\n            batch = items[i:i+batch_size]\n            premises = [f"Tentang {item[0]}" for item in batch]  # v4: entity premise\n            contexts = [item[1] for item in batch]\n            enc = self.tokenizer(premises, contexts, truncation=True, max_length=self.max_seq_length,\n                                 padding=True, return_tensors="pt")\n            with torch.no_grad():\n                outputs = self.model(input_ids=enc["input_ids"].to(self.device),\n                                    attention_mask=enc["attention_mask"].to(self.device))\n                logits = outputs.logits\n                if self.temperature != 1.0: logits = logits / self.temperature\n                probs = F.softmax(logits, dim=-1)\n            for j, (entity, context) in enumerate(batch):\n                prob = probs[j].cpu().tolist()\n                pred_id = int(max(range(len(prob)), key=lambda x: prob[x]))\n                confidence = float(prob[pred_id])\n                result = {"label": ID_LABEL[pred_id], "confidence": confidence,\n                          "deferred": confidence < self.confidence_tau, "entity": entity}\n                if return_all:\n                    result["probabilities"] = {SENTIMENT_LABELS[k]: float(prob[k]) for k in range(len(SENTIMENT_LABELS))}\n                all_results.append(result)\n        return all_results\n\n    def predict_with_deferral(self, entity, context):\n        result = self.predict(entity, context)\n        if result["deferred"]: result["label"] = "ABSTAIN"\n        return result\n\n    def get_config(self):\n        return {"adapter_path": self.adapter_path, "max_seq_length": self.max_seq_length,\n                "temperature": self.temperature, "confidence_tau": self.confidence_tau,\n                "device": str(self.device), "labels": SENTIMENT_LABELS, "model_version": "v6 (v4 LoRA)"}\n\n\ndef load_model(adapter_path, base_model=DEFAULT_BASE_MODEL, temperature=DEFAULT_TEMPERATURE,\n               confidence_tau=DEFAULT_CONFIDENCE_TAU):\n    return SentimentModelV6(adapter_path=adapter_path, base_model=base_model,\n                           temperature=temperature, confidence_tau=confidence_tau)\n\n\nif __name__ == "__main__":\n    import argparse\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--adapter", required=True)\n    ap.add_argument("--entity", required=True)\n    ap.add_argument("--context", required=True)\n    args = ap.parse_args()\n    model = load_model(args.adapter)\n    result = model.predict(args.entity, args.context, return_all=True)\n    print(json.dumps(result, indent=2, ensure_ascii=False))\n',
    'colab_complete_pipeline_v4.py': '"""\ncolab_complete_pipeline_v4.py\n=============================\nComplete Colab pipeline for v4 fine-tuning.\n\nSteps: install deps → clone repo → fine-tune sentiment → fine-tune relevancy\n       → evaluate → upload to HuggingFace → print summary\n\nUsage:\n  python colab_complete_pipeline_v4.py --steps all\n  python colab_complete_pipeline_v4.py --steps sentiment-only\n"""\nimport os, sys, json, argparse, subprocess\nfrom pathlib import Path\n\nREPO_URL = "https://github.com/raynzz455/ID-Political-Sentiment-Tracker.git"\nREPO_DIR = "/content/ID-Political-Sentiment-Tracker"\nHF_TOKEN_ENV = "HF_TOKEN"\nHF_MODEL_SENTIMENT = "raynzz455/id-political-sentiment-sentiment-v4"\nHF_MODEL_RELEVANCY = "raynzz455/id-political-sentiment-relevancy-v4"\nDATASET = "dataset_gold_standard_final.jsonl"\nK_FOLD = 5\n\ndef run(cmd, cwd=None, check=True):\n    print(f"\\n$ {cmd}")\n    result = subprocess.run(cmd, shell=True, cwd=cwd, stdout=sys.stdout, stderr=sys.stderr, text=True)\n    if check and result.returncode != 0:\n        print(f"FAILED: code {result.returncode}"); sys.exit(result.returncode)\n    return result\n\ndef step_install():\n    print("\\n=== STEP 1: Install ===")\n    run("pip install -q transformers peft scikit-learn accelerate sentencepiece")\n    run(\'python -c "import torch; print(f\\\'CUDA: {torch.cuda.is_available()}\\\')"\')\n\ndef step_clone():\n    print("\\n=== STEP 2: Clone ===")\n    if not Path(REPO_DIR).exists():\n        run(f"git clone {REPO_URL} {REPO_DIR}")\n    else:\n        run(f"cd {REPO_DIR} && git pull", check=False)\n    ds = Path(REPO_DIR) / "finetuning" / "datasets" / DATASET\n    if not ds.exists():\n        print(f"ERROR: {ds} not found. Run cleaning pipeline first."); sys.exit(1)\n    run(f"wc -l {ds}")\n\ndef step_finetune_sentiment():\n    print("\\n=== STEP 3: Fine-tune Sentiment ===")\n    run(f"cd {REPO_DIR}/finetuning && python finetune_v4.py --task sentiment --kfold {K_FOLD}")\n\ndef step_finetune_relevancy():\n    print("\\n=== STEP 4: Fine-tune Relevancy ===")\n    run(f"cd {REPO_DIR}/finetuning && python finetune_v4.py --task relevancy --kfold {K_FOLD}")\n\ndef step_evaluate():\n    print("\\n=== STEP 5: Evaluate ===")\n    for task, dir_name in [("sentiment","sentiment_v4"), ("relevancy","relevancy_v4")]:\n        kf = Path(REPO_DIR)/"finetuning"/"runs"/dir_name/"kfold_results.json"\n        if kf.exists():\n            print(f"\\n--- {task} K-fold ---")\n            run(f\'cd {REPO_DIR}/finetuning && python evaluate_v4.py --task {task} --kfold-results {kf}\')\n\ndef step_upload():\n    print("\\n=== STEP 6: Upload ===")\n    token = os.environ.get(HF_TOKEN_ENV)\n    if not token:\n        print(f"{HF_TOKEN_ENV} not set. Skipping upload."); return\n    run(f"huggingface-cli login --token {token}")\n    for task, hf_model, dir_name in [\n        ("sentiment", HF_MODEL_SENTIMENT, "sentiment_v4"),\n        ("relevancy", HF_MODEL_RELEVANCY, "relevancy_v4"),\n    ]:\n        kf = Path(REPO_DIR)/"finetuning"/"runs"/dir_name/"kfold_results.json"\n        if kf.exists():\n            kfold = json.load(open(kf))\n            best = max(kfold.get("fold_results",[]), key=lambda x: x.get("macro_f1",0))\n            fold_dir = Path(REPO_DIR)/"finetuning"/"runs"/dir_name/f"fold_{best.get(\'fold\',1)}"\n            if fold_dir.exists():\n                print(f"Uploading {task} (fold {best.get(\'fold\')}, f1={best.get(\'macro_f1\',0):.4f})")\n                run(f"huggingface-cli upload {hf_model} {fold_dir} --token {token}")\n\ndef step_summary():\n    print("\\n=== COMPLETE ===")\n    for task, dir_name in [("sentiment","sentiment_v4"), ("relevancy","relevancy_v4")]:\n        kf = Path(REPO_DIR)/"finetuning"/"runs"/dir_name/"kfold_results.json"\n        if kf.exists():\n            kfold = json.load(open(kf))\n            print(f"{task}: acc={kfold.get(\'mean_accuracy\',0):.4f} ± {kfold.get(\'std_accuracy\',0):.4f}, "\n                  f"f1={kfold.get(\'mean_macro_f1\',0):.4f} ± {kfold.get(\'std_macro_f1\',0):.4f}")\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--steps", default="all")\n    args = ap.parse_args()\n    steps = args.steps.lower().split(",")\n    if "all" in steps: steps = ["install","clone","sentiment","relevancy","evaluate","upload","summary"]\n    elif "sentiment-only" in steps: steps = ["install","clone","sentiment","evaluate","summary"]\n    step_map = {"install":step_install,"clone":step_clone,"sentiment":step_finetune_sentiment,\n                "relevancy":step_finetune_relevancy,"evaluate":step_evaluate,"upload":step_upload,"summary":step_summary}\n    for s in steps:\n        s = s.strip()\n        if s in step_map: step_map[s]()\n\nif __name__ == "__main__":\n    main()\n',
}

def main():
    print("=" * 60)
    print("SETUP COLAB v4")
    print("=" * 60)

    # Step 1: Clone repo
    if not Path(REPO_DIR).exists():
        print("\n1. Cloning repo...")
        run(f"git clone {REPO_URL} {REPO_DIR}")
    else:
        print(f"\n1. Repo exists: {REPO_DIR}")

    # Step 2: Write v4 files
    print("\n2. Writing v4 scripts...")
    file_map = {
        'finetune_v4.py': 'finetuning/finetune_v4.py',
        'evaluate_v4.py': 'finetuning/evaluate_v4.py',
        'hyperparams_v4.py': 'finetuning/configs/hyperparams_v4.py',
        'sentiment_model_v6.py': 'finetuning/patches/sentiment_model_v6.py',
        'colab_complete_pipeline_v4.py': 'finetuning/colab_complete_pipeline_v4.py',
    }
    for src_name, dst_path in file_map.items():
        full_dst = Path(REPO_DIR) / dst_path
        full_dst.parent.mkdir(parents=True, exist_ok=True)
        full_dst.write_text(EMBEDDED_FILES[src_name])
        print(f"  Written: {dst_path} ({len(EMBEDDED_FILES[src_name])} chars)")

    # Step 3: Copy dataset
    print("\n3. Copying dataset...")
    ds_src = Path("/content/dataset_gold_standard_final.jsonl")
    ds_dst = Path(REPO_DIR) / "finetuning" / "datasets" / "dataset_gold_standard_final.jsonl"
    ds_dst.parent.mkdir(parents=True, exist_ok=True)
    if ds_src.exists():
        import shutil
        shutil.copy2(ds_src, ds_dst)
        count = sum(1 for _ in open(ds_dst))
        print(f"  Dataset copied: {count} rows")
    else:
        print(f"  ERROR: Upload dataset_gold_standard_final.jsonl to /content/ first!")
        sys.exit(1)

    # Step 4: Verify
    print("\n4. Verifying...")
    for f in ['finetuning/finetune_v4.py', 'finetuning/evaluate_v4.py',
              'finetuning/configs/hyperparams_v4.py', 'finetuning/datasets/dataset_gold_standard_final.jsonl']:
        p = Path(REPO_DIR) / f
        status = "OK" if p.exists() else "MISSING"
        print(f"  {status}: {f}")

    print("\n" + "=" * 60)
    print("SETUP COMPLETE!")
    print("=" * 60)
    print(f"\nNext steps:")
    print(f"  %cd {REPO_DIR}/finetuning")
    print(f"  !python finetune_v4.py --task sentiment --kfold 5")
    print(f"\nOr evaluate after training:")
    print(f"  !python evaluate_v4.py --task sentiment --kfold-results runs/sentiment_v4/kfold_results.json")

if __name__ == "__main__":
    main()
